import { log } from './log.js';
const isLightningCSSError = (err) => {
    return err instanceof SyntaxError && 'fileName' in err && typeof err.fileName === 'string';
};
export const handleLightningCSSErrors = (err) => {
    if (isLightningCSSError(err)) {
        if (err.data === 'ResolverError') {
            log.error('Could not resolve an @import. Check if the path exists or is spelled correctly.');
        }
        else if (err.loc) {
            log.error(['Error found at:', `\t- Line: ${err.loc.line}`, `\t- Column: ${err.loc.column}`]);
        }
    }
    throw err;
};
